INSERT INTO "emailtemplates" ("id","TemplateName","TemplateText","Subject","SenderName","SenderEmail","AlertChannel","AlertLanguageCode","Alert_id") VALUES ('5','APPLICATION_SUCCESSFUL_SUBMISSION_EMAIL_TEMPLATE',TO_CLOB('<html> <head> <title> KONY HTML TEMPLATE </title> </head> <body> <table width="100%" align="center" cellpadding="0" cellspacing="0" border="0" valign="top" bgcolor="#FFFFFF"> <tbody> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:14px 24px;border-bottom:3px solid #0A78D1;font-family:sans-serif;font-weight:400;"> <img src="https://www.dropbox.com/s/yv01ja4p8mdmz65/konydbxlogo_customer_landing.png?raw=1" alt="logo" style="display:inline-block;float:left;vertical-align:middle;width:178px;height:35px;"/> <a target="_blanc" href="https://dbx.kony.com/" style="float:right;padding-top:11px;display:inline-block;font-size:14px;line-height:14px;text-decoration:none;color:#0A78D1;">dbx.kony.com</a> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:25px 23px 0 23px;font-family:sans-serif;font-weight:400;"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">Dear</span> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">%APPLICANT_NAME%,</span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:14px 23px 0 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">We received your application on %DATE_OF_SUBMISSION% and appreciate your interest in %LOAN_TYPE%. </span> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">For your reference your application number is %APPLICATION_NUMBER% If you recognize this application, no further action is necessary and you 